y.0}}}{1}$ point, sur le segment $[AB]$.|les deux rayons ne suffisent pas à couvrir $AB$, les cercles ne se touchent pas : $\\textcolor{{{color:primary.0}}}{0}$ point.}}}}"]}},{"statement":"Deux cercles ont pour centre $O$ : le petit a pour rayon ${{eval:a/10;d}}~\\unit{cm}$, le grand ${{eval:b/10;d}}~\\unit{cm}$.\n\n```figure\nfenetre: -6 ; 6 ; -6 ; 6\ndescription: Deux cercles de centre O, un petit et un grand, et un point M.\n---\nO = point(0, 0, etiquette=\"bas\")\ncercle(O, rayon={{eval:a/10;d}}, couleur=\"bleu\", epaisseur=2)\ncercle(O, rayon={{eval:b/10;d}}, couleur=\"bleu\", epaisseur=2)\nM = point(O, longueur={{eval:d;d}}, angle={{t}}, etiquette=\"haut\", couleur=\"rouge\")\n```\n\nQue peut-on dire de la distance $OM$ ?\n\n```choix\nplusieurs: oui\nmelanger: non\n- $OM$ est plus grand que ${{eval:a/10;d}}~\\unit{cm}$\n- $OM$ est plus petit que ${{eval:a/10;d}}~\\unit{cm}$\n- $OM$ est plus grand que ${{eval:b/10;d}}~\\unit{cm}$\n- $OM$ est plus petit que ${{eval:b/10;d}}~\\unit{cm}$\n```","variables":[{"name":"k","expression":"0..2"},{"name":"a","expression":"15..25"},{"name":"b","expression":"35..45"},{"name":"t","expression":"20..160"},{"name":"d","expression":"eval:((a+b)/20)*(1-min(abs(k-0),1))+(a/20)*(1-min(abs(k-1),1))+(b/10+1)*(1-min(abs(k-2),1))"}],"blanks":[{"expectedAnswer":"{{if:k==0|0;3|{{if:k==1|1;3|0;2}}}}"}],"correction":{"steps":["On compare $OM$ à chacun des deux rayons : $M$ est-il dans le petit disque ? dans le grand ?","{{if:k==0|$M$ est entre les deux cercles : hors du petit disque, $\\textcolor{{{color:primary.0}}}{OM > {{eval:a/10;d}}~\\unit{cm}}$ ; dans le grand, $\\textcolor{{{color:primary.0}}}{OM < {{eval:b/10;d}}~\\unit{cm}}$.|{{if:k==1|$M$ est dans le petit disque : $\\textcolor{{{color:primary.0}}}{OM < {{eval:a/10;d}}~\\unit{cm}}$, et donc aussi $\\textcolor{{{color:primary.0}}}{OM < {{eval:b/10;d}}~\\unit{cm}}$.|$M$ est hors du grand disque : $\\textcolor{{{color:primary.0}}}{OM > {{eval:b/10;d}}~\\unit{cm}}$, et donc aussi $\\textcolor{{{color:primary.0}}}{OM > {{eval:a/10;d}}~\\unit{cm}}$.}}}}"]},"hint":"Regarde d'abord le petit cercle : $M$ est-il dedans ou dehors ? Puis le grand."},{"statement":"Le disque bleu a pour centre $A$ et pour rayon ${{eval:a/10;d}}~\\unit{cm}$ ; le disque rouge a pour centre $B$ et pour rayon ${{eval:b/10;d}}~\\unit{cm}$.\n\n```figure\nfenetre: -4.5 ; 8 ; -4 ; 4\ndescription: Deux disques qui se chevauchent, un bleu de centre A et un rouge de centre B, et un point M.\n---\nA = point(0, 0, etiquette=\"bas\")\nB = point(4, 0, etiquette=\"bas\")\ncercle(A, rayon={{eval:a/10;d}}, couleur=\"bleu\", epaisseur=2, remplissage=\"bleu\", opacite_fond=0.15)\ncercle(B, rayon={{eval:b/10;d}}, couleur=\"rouge\", epaisseur=2, remplissage=\"rouge\", opacite_fond=0.15)\nM = point({{eval:x;d}}, 1, etiquette=\"haut\", couleur=\"noir\")\n```\n\nQue peut-on dire des distances $MA$ et $MB$ ?\n\n```choix\nplusieurs: oui\nmelanger: non\n- $MA$ est plus petit que ${{eval:a/10;d}}~\\unit{cm}$\n- $MA$ est plus grand que ${{eval:a/10;d}}~\\unit{cm}$\n- $MB$ est plus petit que ${{eval:b/10;d}}~\\unit{cm}$\n- $MB$ est plus grand que ${{eval:b/10;d}}~\\unit{cm}$\n```","variables":[{"name":"k","expression":"0..2"},{"name":"a","expression":"28..35"},{"name":"b","expression":"25..30"},{"name":"x","expression":"eval:((4-b/10+a/10)/2)*(1-min(abs(k-0),1))+(-a/20)*(1-min(abs(k-1),1))+(4+b/20)*(1-min(abs(k-2),1))"}],"blanks":[{"expectedAnswer":"{{if:k==0|0;2|{{if:k==1|0;3|1;2}}}}"}],"correction":{"steps":["$M$ est dans le disque bleu si $MA$ est plus petit que son rayon, dans le disque rouge si $MB$ est plus petit que le sien.","{{if:k==0|$M$ est dans la partie commune : dans les deux disques, $\\textcolor{{{color:primary.0}}}{MA < {{eval:a/10;d}}~\\unit{cm}}$ et $\\textcolor{{{color:primary.0}}}{MB < {{eval:b/10;d}}~\\unit{cm}}$.|{{if:k==1|$M$ est dans le disque bleu seulement : $\\textcolor{{{color:primary.0}}}{MA < {{eval:a/10;d}}~\\unit{cm}}$ et $\\textcolor{{{color:primary.0}}}{MB > {{eval: